mapper.select:
SELECT GROUP_ID, OWNER_ID, TITLE, STATUS, AMOUNT, MAX_MEMBERS
FROM GYE_GROUP
WHERE GROUP_ID = #{groupId}

SELECT dr.DISSOLUTION_REQUEST_ID AS dissolutionRequestId, dr.GROUP_ID AS groupId, g.TITLE AS groupTitle, g.STATUS AS groupStatus, dr.REQUESTED_BY AS requestedBy, m.NAME AS leaderName, dr.REASON AS reason, dr.STATUS AS status, dr.DECIDED_BY AS decidedBy, dr.DECIDED_AT AS decidedAt, dr.CREATED_AT AS createdAt, (SELECT COUNT(*) FROM GYE_MEMBER gm WHERE gm.GROUP_ID = dr.GROUP_ID AND gm.STATUS = 'ACTIVE') AS memberCount, (SELECT COUNT(*) FROM PAYMENT_PROOF pp WHERE pp.GROUP_ID = dr.GROUP_ID AND pp.STATUS != 'CONFIRMED') AS unconfirmedProofCount, (SELECT COUNT(*) FROM WITHDRAWAL_REQUEST wr WHERE wr.GROUP_ID = dr.GROUP_ID AND wr.STATUS IN ('SETTLEMENT_PENDING', 'CONSENT_PENDING')) AS activeWithdrawalCount, (SELECT NVL(SUM(pp2.AMOUNT), 0) FROM PAYMENT_PROOF pp2 WHERE pp2.GROUP_ID = dr.GROUP_ID AND pp2.STATUS = 'CONFIRMED') AS totalConfirmedAmount FROM DISSOLUTION_REQUEST dr JOIN GYE_GROUP g ON dr.GROUP_ID = g.GROUP_ID JOIN MEMBER m ON dr.REQUESTED_BY = m.MEMBER_ID
AND dr.STATUS = #{status}
ORDER BY CASE WHEN dr.STATUS = 'PENDING' THEN 0 ELSE 1 END, dr.CREATED_AT DESC

mapper.update:
UPDATE GYE_GROUP
SET STATUS     = #{status},
    UPDATED_AT = SYSDATE
WHERE GROUP_ID = #{groupId}
  AND STATUS = #{expectedStatus}
